236:     data->dpi = Dpi{ Utils::getWindowDpi(data->windowId, true), Utils::getWindowDpi(data->windowId, false) };
237:     DEBUG.noquote() << "The DPI of window" << hwnd2str(data->windowId) << "is" << data->dpi;
238:     data->monitor = ::MonitorFromWindow(reinterpret_cast<HWND>(data->windowId), MONITOR_DEFAULTTONEAREST);
239:     Q_ASSERT(data->monitor);
240:     if (!data->monitor) {
241:         WARNING << Utils::getSystemErrorMessage(kMonitorFromWindow);
242:     }
243:     // Remove the bad window styles added by Qt (it's not that "bad" though).
244:     std::ignore = Utils::maybeFixupQtInternals(data->windowId);
245: #if 0
246:     data->callbacks->setWindowFlags(data->callbacks->getWindowFlags() | Qt::FramelessWindowHint);
247: #else
248: #  if ((QT_VERSION != QT_VERSION_CHECK(6, 5, 3)) && (QT_VERSION != QT_VERSION_CHECK(6, 6, 0)))
249:     // Qt maintains a frame margin internally, we need to update it accordingly
250:     // otherwise we'll get lots of warning messages when we change the window
251:     // geometry, it will also affect the final window geometry because QPA will
252:     // always take it into account when setting window size and position.
253:     std::ignore = Utils::updateInternalWindowFrameMargins(qWindow, true);
254: #  endif
255: #endif
256:     // Tell DWM our preferred frame margin.
257:     std::ignore = Utils::updateWindowFrameMargins(data->windowId, false);
258:     // Tell DWM we don't use the window icon/caption/sysmenu, don't draw them.
259:     std::ignore = Utils::hideOriginalTitleBarElements(data->windowId);
260:     // Without this hack, the child windows can't get DPI change messages from
261:     // Windows, which means only the top level windows can be scaled to the correct
262:     // size, we of course don't want such thing from happening.
263:     std::ignore = Utils::fixupChildWindowsDpiMessage(data->windowId);
264: #if 0 // Conflicts with our blur mode setting.
265:     // If we are using 3D APIs (D3D, Vulkan, OpenGL, etc) to draw the window content,
266:     // we need to setup the DWM rendering policy as well.
267:     if (Utils::isWindowAccelerated(qWindow) && Utils::isWindowTransparent(qWindow)) {
268:         std::ignore = Utils::updateFramebufferTransparency(data->windowId);
269:     }
270: #endif
271:     if (WindowsVersionHelper::isWin10RS1OrGreater()) {
272:         // Tell DWM we may need dark theme non-client area (title bar & frame border).
273:         FramelessHelperEnableThemeAware();
274:         if (WindowsVersionHelper::isWin10RS5OrGreater()) {
275:             const bool dark = (FramelessManager::instance()->systemTheme() == SystemTheme::Dark);
276:             const auto isWidget = [&data]() -> bool {
277:                 const QObject *widget = data->callbacks->getWidgetHandle();
278:                 return (widget && widget->isWidgetType());
279:             }();
280:             if (!isWidget) {
281:                 // Tell UXTheme we may need dark theme controls.
282:                 // Causes some QtWidgets paint incorrectly, so only apply to Qt Quick applications.
283:                 std::ignore = Utils::updateGlobalWin32ControlsTheme(data->windowId, dark);
284:             }
285:             std::ignore = Utils::refreshWin32ThemeResources(data->windowId, dark);
286:             if (WindowsVersionHelper::isWin11OrGreater()) {
287:                 // DWM provides official API to adjust the window corner style, but only since Windows 11.
288:                 if (FramelessConfig::instance()->isSet(Option::WindowUseSquareCorners)) {
289:                     std::ignore = Utils::setCornerStyleForWindow(data->windowId, WindowCornerStyle::Square);
290:                 }
291:             }
292:         }
293:     }
294:     if (!g_internalData()->eventFilter) {
295:         g_internalData()->eventFilter = std::make_unique<FramelessHelperWin>();
