305: bool FramelessHelperWin::nativeEventFilter(const QByteArray &eventType, void *message, QT_NATIVE_EVENT_RESULT_TYPE *result)
306: {
307:     if ((eventType != qtNativeEventType()) || !message || !result) {
308:         return false;
309:     }
310:     // QPA by default stores the global mouse position in the pt field,
311:     // but let's not reply on such Qt-specific extensions.
312: #if (QT_VERSION == QT_VERSION_CHECK(5, 11, 1))
313:     // Work-around a bug caused by typo which only exists in Qt 5.11.1
314:     const auto msg = *static_cast<MSG **>(message);
315: #else
316:     const auto msg = static_cast<const MSG *>(message);
317: #endif
318:     const HWND hWnd = msg->hwnd;
319:     if (!hWnd) {
320:         // Why sometimes the window handle is null? Is it designed to be like this?
321:         // Anyway, we should skip the entire processing in this case.
322:         return false;
323:     }
324: 
325:     const UINT uMsg = msg->message;
326:     // We should skip these messages otherwise we will get crashes.
327:     // NOTE: WM_QUIT won't be posted to the WindowProc function.
328:     switch (uMsg) {
329:     case WM_CLOSE:
330:     case WM_DESTROY:
331:     case WM_NCDESTROY:
332:     // Undocumented messages:
333:     case WM_UAHDESTROYWINDOW:
334:     case WM_UNREGISTER_WINDOW_SERVICES:
335:         return false;
336:     default:
337:         break;
338:     }
339: 
340:     const auto windowId = reinterpret_cast<WId>(hWnd);
341:     // Let's be extra safe.
342:     if (!Utils::isValidWindow(windowId, false, true)) {
343:         return false;
344:     }
345: 
346:     const QObject *window = FramelessManagerPrivate::getWindow(windowId);
347:     if (!window) {
348:         return false;
349:     }
350:     const FramelessDataWinPtr data = tryGetData(window);
351:     if (!data || !data->frameless || !data->callbacks) {
352:         return false;
353:     }
354: 
355:     QWindow *qWindow = data->callbacks->getWindowHandle();
356: 
357:     const bool frameBorderVisible = Utils::isWindowFrameBorderVisible();
358: 
359:     const WPARAM wParam = msg->wParam;
360:     const LPARAM lParam = msg->lParam;
361: 
362: #if (QT_VERSION < QT_VERSION_CHECK(6, 5, 1))
363:     const auto updateRestoreGeometry = [windowId, &data](const bool ignoreWindowState) -> void {
364:         if (!ignoreWindowState && !Utils::isWindowNoState(windowId)) {
365:             return;
366:         }
367:         const QRect rect = Utils::getWindowRestoreGeometry(windowId);
368:         if (!Utils::isValidGeometry(rect)) {
369:             WARNING << "The calculated restore geometry is invalid.";
370:             return;
371:         }
372:         if (Utils::isValidGeometry(data->restoreGeometry) && (data->restoreGeometry == rect)) {
373:             return;
374:         }
375:         data->restoreGeometry = rect;
376:     };
377: #endif // (QT_VERSION < QT_VERSION_CHECK(6, 5, 1))
378: 
379:     const auto emulateClientAreaMessage = [hWnd, uMsg, wParam, lParam](const std::optional<int> &overrideMessage = std::nullopt) -> void {
380:         const int myMsg = overrideMessage.value_or(uMsg);
381:         const auto wparam = [myMsg, wParam]() -> WPARAM {
382:             if (myMsg == WM_NCMOUSELEAVE) {
383:                 // wParam is always ignored in mouse leave messages, but here we
384:                 // give them a special tag to be able to distinguish which messages
385:                 // are sent by ourselves.
386:                 return kMessageTag;
387:             }
388:             const quint64 keyState = Utils::getKeyState();
389:             if ((myMsg >= WM_NCXBUTTONDOWN) && (myMsg <= WM_NCXBUTTONDBLCLK)) {
390:                 const auto xButtonMask = GET_XBUTTON_WPARAM(wParam);
391:                 return MAKEWPARAM(keyState, xButtonMask);
392:             }
393:             return keyState;
394:         }();
395:         const auto lparam = [myMsg, lParam, hWnd]() -> LPARAM {
396:             if (myMsg == WM_NCMOUSELEAVE) {
397:                 // lParam is always ignored in mouse leave messages.
398:                 return 0;
399:             }
400:             const auto screenPos = POINT{ GET_X_LPARAM(lParam), GET_Y_LPARAM(lParam) };
401:             POINT clientPos = screenPos;
402:             if (::ScreenToClient(hWnd, &clientPos) == FALSE) {
403:                 WARNING << Utils::getSystemErrorMessage(kScreenToClient);
404:                 return 0;
405:             }
406:             return MAKELPARAM(clientPos.x, clientPos.y);
407:         }();
408: #if 0
409: #  define SEND_MESSAGE ::SendMessageW
410: #else
411: #  define SEND_MESSAGE ::PostMessageW
412: #endif
413:         switch (myMsg) {
